286→export interface ScanMetricOverFramesResult {
287→  data: StatsPack;
288→  provenance: Provenance;
289→}
290→
291→export function scanMetricOverFrames(
292→  db: Database.Database,
293→  args: ScanMetricOverFramesArgs
294→): ScanMetricOverFramesResult {
295→  const { runId, markerName, thread, metric = 'selfMs' } = args;
296→  const col = metric === 'totalMs' ? 'total_ms' : 'self_ms';
297→
298→  // Get all frame indices for this run (the full time axis)
299→  const allFrames = db
300→    .prepare(
301→      'SELECT frame_index FROM prism_frame_meta WHERE run_id = ? ORDER BY frame_index'
302→    )
303→    .all(runId) as Array<{ frame_index: number }>;
304→
305→  // Get per-frame sums where the marker is present
306→  let markerSql = `
307→    SELECT frame_index, SUM(${col}) AS v
308→    FROM prism_frame_marker_samples
309→    WHERE run_id = ? AND marker_name = ?
310→  `;
311→  const params: unknown[] = [runId, markerName];
312→  if (thread) {
313→    markerSql += ' AND thread = ?';
314→    params.push(thread);
315→  }
316→  markerSql += ' GROUP BY frame_index';
317→
318→  const markerRows = db.prepare(markerSql).all(...params) as Array<{
319→    frame_index: number;
320→    v: number;
321→  }>;
322→
323→  // Build dense series aligned to allFrames (zero for absent frames)
324→  const markerMap = new Map<number, number>();
325→  for (const r of markerRows) markerMap.set(r.frame_index, r.v);
326→
327→  const values: number[] = [];
328→  const frameIndices: number[] = [];
329→  for (const { frame_index } of allFrames) {
330→    values.push(markerMap.get(frame_index) ?? 0);
331→    frameIndices.push(frame_index);
332→  }
333→
334→  const stats = computeStatsPack(values, frameIndices);
335→
336→  return {
337→    data: stats,
338→    provenance: {
339→      runId,
340→      tool: 'scanMetricOverFrames',
341→      args: args as Record<string, unknown>,
342→    },
343→  };
344→}
